    "property_id": "PROP-legion-backe-inv-018",
    "audit_result": {
      "property_id": "PROP-legion-backe-inv-018",
      "classification": "potential-vulnerability",
      "code_path": "src/raise/LegionCapitalRaise.sol::emergencyWithdraw::L223-229",
      "proof_trace": "The `emergencyWithdraw` function accepts an unconstrained `token` and `amount` parameter with only `onlyLegion` access control, performing no check that `token != bidToken` and no minimum balance guard ensuring `balance \u2212 amount >= sum(investedCapital)`. Because no accounting state is updated, a Legion bouncer call with the bidToken drains the contract while all investor `investedCapital` values remain positive, directly breaking the solvency invariant at any point in the raise lifecycle.",
      "attack_scenario": "A compromised or malicious Legion bouncer calls `emergencyWithdraw(attackerAddress, bidToken, contractBalance)` while investors have active positions; all bidToken is transferred out but `investedCapital` entries remain nonzero, causing all subsequent `refund()` and `withdrawInvestedCapitalIfCanceled()` calls to revert due to insufficient balance.",
      "checklist_id": "PROP-legion-backe-inv-018"
    },
    "text": "Contract bidToken balance must be >= sum of all unclaimed investor positions at all times.",
    "assertion": "bidToken.balanceOf(sale) >= sum(investor.investedCapital for active investors)",
    "covers": "SG-002",
    "severity": "CRITICAL",
    "type": "invariant"
  }
}

